import json,re,statistics
from transformers import AutoTokenizer
tok=AutoTokenizer.from_pretrained("/user/user1/harbor-runs/6618a6393290/workspace/models/Qwen2.5-0.5B-Instruct")
BASE="/user/user1/harbor-runs/6618a6393290/workspace/results/run100"
HASH=re.compile(r"####\s*(-?[0-9\.\,]+)"); BOX=re.compile(r"\\boxed\{([^}]*)\}"); NUM=re.compile(r"-?\d[\d,]*(?:\.\d+)?")
def norm(s):
    s=str(s).replace(",","").replace("$","").strip().rstrip(".")
    sign="-" if s.startswith("-") else ""; s=s.lstrip("-").lstrip("0") or "0"
    if "." in s: s=s.rstrip("0").rstrip(".") or "0"
    return sign+s
def nums(o): return {norm(x) for x in NUM.findall(o or "")}
def stated(o):
    m=HASH.findall(o or "")
    if m: return norm(m[-1])
    m=BOX.findall(o or "")
    if m: return norm(m[-1])
    return None

print("EXPLOIT TEST: among held-out items where the model's STATED answer is WRONG (genuine failure),")
print("does emitting more distinct numbers still buy loose reward?\n")
for step in [0,100]:
