    for k in sorted(bk):
        c,s=bk[k]
        if c>=8: print(f"   {k:>2}-{k+4:<2} distinct numbers: n={c:<4} loose-reward rate={s/c:.3f}")
    # also: token length vs loose credit among genuine failures
    lb={}
    for i in wrong:
        b=min(L[i]//128*128,512); lb.setdefault(b,[0,0]); lb[b][0]+=1; lb[b][1]+=rows[i]["score"]
    print("   by response token length:")
    for b in sorted(lb):
        c,s=lb[b]
        if c>=8: print(f"     {b:>3}-{b+127:<3} tokens: n={c:<4} loose-reward rate={s/c:.3f}")
    print()
